import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Entities – Write","description":"","frontmatter":{"title":"Entities – Write"},"headers":[],"relativePath":"de/api/reference/entities-write.md","filePath":"de/api/reference/entities-write.md"}`),a={name:`de/api/reference/entities-write.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="entities-–-write" tabindex="-1">Entities – Write <a class="header-anchor" href="#entities-–-write" aria-label="Permalink to “Entities – Write”">​</a></h1><div><p>Operationen des Tags <strong>Entities – Write</strong>, die dieses Release implementiert. Erzeugt aus <code>api/openapi.yaml</code>; geplante Operationen sind nicht aufgeführt. Die Beschreibungen stammen aus dem englischen API-Vertrag.</p><h2 id="batchWriteEntities" tabindex="-1">Create/update entities and connections in batch <a class="header-anchor" href="#batchWriteEntities" aria-label="Permalink to “Create/update entities and connections in batch”">​</a></h2><p><code>POST /entities/batch</code> · <code>batchWriteEntities</code></p><p>Writes up to 500 entities and 500 connections in one request. The preferred endpoint for external systems with <code>strategy: upsert</code> (ADR-026). <code>?dryRun=true</code> → validation without persisting. Connections are written after the entities; their endpoints are checked against the connection metatype (codes <code>SOURCE_REQUIRED</code>, <code>SOURCE_AMBIGUOUS</code>, <code>SOURCE_NOT_FOUND</code>, <code>SOURCE_NOT_ALLOWED</code>, the same for <code>TARGET_</code>, <code>METATYPE_NOT_CONNECTION</code> and <code>ENDPOINT_CHANGE_NOT_SUPPORTED</code>). An update of an entity with an open issue of a solution fails with <code>OPEN_ISSUES</code> (US-153 AC1). Not supported yet: <code>dryRun=true</code> (US-141 AC3) is rejected with 422; <code>parentId</code> and <code>lifecycle</code> are item errors. <code>X-Agent-Id</code> is stored only as the informational audit field <code>agent_label</code> (ADR-033 §7). A batch with a connection of a metatype that is the <code>scopingConnectionType</code> of a property definition needs <code>visibility-scope:assign</code>; without it the whole batch is rejected with 403 (REQ-161). A value of a <code>role-restricted</code> property, set or removed, needs one of its write roles, and a value of a <code>connection-scoped</code> property an existing entity in the writer&#39;s scope; otherwise the whole batch is rejected with 403 (REQ-126, REQ-127). A property not named keeps its value.</p><p><strong>Zugriff</strong>: Berechtigung <code>entity:write</code>; zusätzlich <code>visibility-scope:assign</code>, wenn: a connection of a type used as scopingConnectionType is written</p><h3 id="parameter" tabindex="-1">Parameter <a class="header-anchor" href="#parameter" aria-label="Permalink to “Parameter”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Ort</th><th>Pflicht</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>dryRun</code></td><td>query</td><td>nein</td><td>boolean</td><td>–</td></tr><tr><td><code>X-Agent-Id</code></td><td>header</td><td>nein</td><td>string</td><td>Informational label of the calling tool (ADR-026, ADR-033 §7). Stored untrusted as <code>agentLabel</code>; never used for attribution, filtering or authorization. Longer values are truncated to 100 characters; control characters are removed.</td></tr><tr><td><code>X-Agent-Run</code></td><td>header</td><td>nein</td><td>string</td><td>Informational correlation ID of a run of the calling tool (stored as <code>agentRun</code>)</td></tr></tbody></table><h3 id="request-body" tabindex="-1">Request-Body <a class="header-anchor" href="#request-body" aria-label="Permalink to “Request-Body”">​</a></h3><ul><li><code>application/json</code>: BatchWriteRequest</li></ul><h3 id="antworten" tabindex="-1">Antworten <a class="header-anchor" href="#antworten" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>200</td><td>Batch result (also for partial errors if atomic=false)</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>422</td><td>Entire batch invalid, nothing written: more entities or connections than the limit, dryRun=true (not supported yet), or atomic=true with at least one faulty item (<code>errors[].field</code> carries the item index, e.g. <code>entities[3].properties</code> or <code>connections[0].sourceExternalId</code>).</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="createConnection" tabindex="-1">Create connection between two entities <a class="header-anchor" href="#createConnection" aria-label="Permalink to “Create connection between two entities”">​</a></h2><p><code>POST /connections</code> · <code>createConnection</code></p><p>Creates a connection, an entity of a connection metatype with a source and a target (US-036, ADR-010). Source and target are referenced by internal ID or <code>externalId</code>; their metatypes must be allowed by the connection metatype (subtypes included) and cannot change afterwards. Without <code>name</code> the connection is named <code>&lt;source name&gt; → &lt;target name&gt;</code>. Properties are checked as for entities. A connection of a metatype that is the <code>scopingConnectionType</code> of a property definition also needs <code>visibility-scope:assign</code>, otherwise 403 (REQ-161). A value of a <code>role-restricted</code> property needs one of its write roles, otherwise 403 (REQ-126); a value of a <code>connection-scoped</code> property cannot be set on creation, because the connection is not yet in the writer&#39;s scope (403, REQ-127).</p><p><strong>Zugriff</strong>: Berechtigung <code>entity:write</code>; zusätzlich <code>visibility-scope:assign</code>, wenn: a connection of a type used as scopingConnectionType is written</p><h3 id="request-body-1" tabindex="-1">Request-Body <a class="header-anchor" href="#request-body-1" aria-label="Permalink to “Request-Body”">​</a></h3><ul><li><code>application/json</code>: ConnectionWrite</li></ul><h3 id="antworten-1" tabindex="-1">Antworten <a class="header-anchor" href="#antworten-1" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>201</td><td>Connection created</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Source or target entity not found (<code>errors</code> with <code>SOURCE_NOT_FOUND</code> or <code>TARGET_NOT_FOUND</code>)</td><td>–</td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>422</td><td>Connection or its properties invalid (error codes as in <code>batchWriteEntities</code>)</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="setEntityParent" tabindex="-1">Set or clear the parent of an element entity (US-135, UC-13) <a class="header-anchor" href="#setEntityParent" aria-label="Permalink to “Set or clear the parent of an element entity (US-135, UC-13)”">​</a></h2><p><code>PUT /entities/{id}/parent</code> · <code>setEntityParent</code></p><p>Places an element entity under another element entity, or clears the parent with <code>parentEntityId: null</code> (US-135, US-136; REQ-141, REQ-142, ADR-021). The change is versioned like other entity changes: it writes the next version of the child, whose history, versions and diffs show the system field <code>parentEntityId</code> (&quot;Parent&quot;) by name, and the audit event <code>entity.parent-changed</code>; the parent keeps its version. A restore does not restore the parent. Setting the parent the entity already has changes nothing and writes no version and no event (<code>composition.reason</code> <code>unchanged</code>).</p><p>The parent is another element entity that is not deleted; connections have no parent and are no parent. A parent that is the entity itself, one of its descendants, a connection, deleted or unknown, or a subtree that would end more than 10 levels below the root (the root level is level 1) gives 422 naming <code>parentEntityId</code>; a connection as child gives 422 naming <code>entityId</code>.</p><p>When neither entity is a structuring aid and the connection metatype marked as composition (<code>isComposition</code>) allows the metatype of the parent as source and that of the child as target, a connection of it from the parent to the child is created in the same transaction and marked <code>autoCreated</code>; otherwise only the parent is stored and <code>composition.reason</code> says why. Clearing or changing the parent soft-deletes the connection auto-created for the previous parent (<code>removedConnectionId</code>), if it is not deleted yet; a connection written by other means stays.</p><p><code>If-Match</code> with the current version of the child is required: 428 without it, 412 <code>stale-version</code> when the entity changed meanwhile. An entity with an open issue of a solution gives 409 <code>entity-blocked</code> (US-153). Needs <code>entity:write</code>.</p><p><strong>Zugriff</strong>: Berechtigung <code>entity:write</code></p><h3 id="parameter-1" tabindex="-1">Parameter <a class="header-anchor" href="#parameter-1" aria-label="Permalink to “Parameter”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Ort</th><th>Pflicht</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>ja</td><td>integer</td><td>Entity ID</td></tr><tr><td><code>If-Match</code></td><td>header</td><td>ja</td><td>string</td><td><code>ETag</code> of the version the client has read (<code>&quot;&lt;version&gt;&quot;</code>). A different version gives 412 <code>stale-version</code> and changes nothing; a missing header gives 428.</td></tr></tbody></table><h3 id="request-body-2" tabindex="-1">Request-Body <a class="header-anchor" href="#request-body-2" aria-label="Permalink to “Request-Body”">​</a></h3><ul><li><code>application/json</code>: EntityParentUpdate</li></ul><h3 id="antworten-2" tabindex="-1">Antworten <a class="header-anchor" href="#antworten-2" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>200</td><td>The parent is set or cleared</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Unknown or deleted entity</td><td>–</td></tr><tr><td>409</td><td>The entity has an open issue of a solution (<code>urn:oea:problem:entity-blocked</code>, US-153 AC1); extension member <code>entities</code> with <code>entityId</code>, <code>entityName</code> and its <code>issues</code>. Nothing changes.</td><td><code>urn:oea:problem:entity-blocked</code></td></tr><tr><td>412</td><td><code>If-Match</code> does not name the current version of the element: someone else changed it meanwhile (problem type <code>urn:oea:problem:stale-version</code>, extension <code>currentVersion</code>). Nothing is changed.</td><td><code>urn:oea:problem:stale-version</code></td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>422</td><td>Problem type <code>urn:oea:problem:validation-failed</code> with <code>invalidFields</code> <code>parentEntityId</code> or <code>entityId</code>; nothing changes</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>428</td><td>The operation requires <code>If-Match</code> with the version the client has read (problem type <code>urn:oea:problem:precondition-required</code>). Nothing is changed.</td><td><code>urn:oea:problem:precondition-required</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="createStructuringAid" tabindex="-1">Create a structuring aid (US-136, UC-13) <a class="header-anchor" href="#createStructuringAid" aria-label="Permalink to “Create a structuring aid (US-136, UC-13)”">​</a></h2><p><code>POST /structuring-aids</code> · <code>createStructuringAid</code></p><p>Creates a structuring aid, a purely navigational grouping (US-136, REQ-141): an entity of the built-in metatype &quot;Structuring aid&quot; with <code>isStructuralGrouper</code> set, at the root level or under <code>parentEntityId</code>. It has no properties, no connections and is not part of a solution. The name is trimmed and has 1–255 characters, the description at most 2000. The parent is checked as for <code>setEntityParent</code> (an element entity that is not deleted, at most 10 levels deep); an invalid one gives 422 naming <code>parentEntityId</code>, an invalid name or description 422 naming <code>name</code> or <code>description</code>; a <code>parentEntityId</code> below 1 gives 422 naming <code>parentEntityId</code> too. Writes version 1 and the audit event <code>entity.created</code>. Needs <code>entity:write</code>.</p><p><strong>Zugriff</strong>: Berechtigung <code>entity:write</code></p><h3 id="request-body-3" tabindex="-1">Request-Body <a class="header-anchor" href="#request-body-3" aria-label="Permalink to “Request-Body”">​</a></h3><ul><li><code>application/json</code>: StructuringAidCreate</li></ul><h3 id="antworten-3" tabindex="-1">Antworten <a class="header-anchor" href="#antworten-3" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>201</td><td>The structuring aid is created</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>422</td><td>Problem type <code>urn:oea:problem:validation-failed</code> with <code>invalidFields</code> <code>name</code>, <code>description</code> or <code>parentEntityId</code>; nothing is created</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="deleteStructuringAid" tabindex="-1">Delete a structuring aid (US-136, UC-13) <a class="header-anchor" href="#deleteStructuringAid" aria-label="Permalink to “Delete a structuring aid (US-136, UC-13)”">​</a></h2><p><code>DELETE /structuring-aids/{id}</code> · <code>deleteStructuringAid</code></p><p>Soft-deletes a structuring aid (ADR-019). Its children move to the root level, each with a new version (<code>entity.parent-changed</code>), and none of them is deleted; the aid is deleted with the audit event <code>entity.deleted</code> (<code>cause</code> <code>structuring-aid-deleted</code>), all in one transaction. An entity that is no structuring aid gives 422 naming <code>entityId</code>. <code>If-Match</code> with the current version of the aid is required (428, 412). The aid or one of its children with an open issue of a solution gives 409 <code>entity-blocked</code>. Needs <code>entity:write</code> and <code>entity:delete</code>.</p><p><strong>Zugriff</strong>: Berechtigung <code>entity:write</code>, <code>entity:delete</code></p><h3 id="parameter-2" tabindex="-1">Parameter <a class="header-anchor" href="#parameter-2" aria-label="Permalink to “Parameter”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Ort</th><th>Pflicht</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>ja</td><td>integer</td><td>Entity ID</td></tr><tr><td><code>If-Match</code></td><td>header</td><td>ja</td><td>string</td><td><code>ETag</code> of the version the client has read (<code>&quot;&lt;version&gt;&quot;</code>). A different version gives 412 <code>stale-version</code> and changes nothing; a missing header gives 428.</td></tr></tbody></table><h3 id="antworten-4" tabindex="-1">Antworten <a class="header-anchor" href="#antworten-4" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>204</td><td>The structuring aid is deleted and its children are at the root level</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Unknown or already deleted entity</td><td>–</td></tr><tr><td>409</td><td>The aid or a child has an open issue of a solution (<code>urn:oea:problem:entity-blocked</code>); nothing changes</td><td><code>urn:oea:problem:entity-blocked</code></td></tr><tr><td>412</td><td><code>If-Match</code> does not name the current version of the element: someone else changed it meanwhile (problem type <code>urn:oea:problem:stale-version</code>, extension <code>currentVersion</code>). Nothing is changed.</td><td><code>urn:oea:problem:stale-version</code></td></tr><tr><td>422</td><td>The entity is no structuring aid (<code>invalidFields</code> <code>entityId</code>); nothing changes</td><td>–</td></tr><tr><td>428</td><td>The operation requires <code>If-Match</code> with the version the client has read (problem type <code>urn:oea:problem:precondition-required</code>). Nothing is changed.</td><td><code>urn:oea:problem:precondition-required</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};